class ProductRepository {
  constructor() {
    this._products = [
      { id: 1, name: 'Steel Hammer', category: 'tools', price: 25 },
      { id: 2, name: 'Rubber Mallet', category: 'tools', price: 15 },
      { id: 3, name: 'Garden Hose', category: 'garden', price: 40 },
      { id: 4, name: 'Steel Rake', category: 'garden', price: 30 },
    ];
  }

  list() {
    return [...this._products];
  }

  search({ q, category, maxPrice } = {}) {
    return this._products.filter((p) => {
      if (q !== undefined && !p.name.toLowerCase().includes(q.toLowerCase())) return false;
      if (category !== undefined && p.category !== category) return false;
      if (maxPrice !== undefined && p.price > maxPrice) return false;
      return true;
    });
  }
}

module.exports = ProductRepository;

